package org.eclipse.rdf4j.federated.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.concurrent.atomic.AtomicBoolean;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class ExplicitEmptyReadDatasetQueryStringTest {

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2 })
	void rejectsEmptyReadSelectionsForSelectAskAndLimit(int form) {
		SimpleDataset empty = new SimpleDataset();
		empty.setExplicitReadDataset(true);
		assertThatThrownBy(() -> query(form, empty)).isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("empty read dataset");
	}

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2 })
	void preservesUnconfiguredAndNamedOnlySelections(int form) throws Exception {
		assertThat(query(form, new SimpleDataset())).isEqualTo(query(form, null));
		SimpleDataset selected = new SimpleDataset();
		selected.addNamedGraph(SimpleValueFactory.getInstance().createIRI("urn:named"));
		String expected = query(form, selected);
		selected.setExplicitReadDataset(true);
		assertThat(query(form, selected)).isEqualTo(expected).contains("FROM NAMED <urn:named>");
	}

	private static String query(int form, Dataset dataset) throws Exception {
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		return switch (form) {
		case 0 -> QueryStringUtil.selectQueryString(pattern, EmptyBindingSet.getInstance(), null, new AtomicBoolean(),
				dataset);
		case 1 -> QueryStringUtil.askQueryString(pattern, EmptyBindingSet.getInstance(), dataset);
		default -> QueryStringUtil.selectQueryStringLimit1(pattern, EmptyBindingSet.getInstance(), dataset);
		};
	}
}
